kubectl -n mariadb patch mariadb mariadb-galera --type=merge -p '{"spec":{"myCnf":"[mariadb]\nmax_connections=333\n"}}'; T2=$(date +%s); sleep 30; until [ "$(kubectl -n mariadb get mariadb mariadb-galera -o jsonpath="{.status.conditions[?(@.type==\"Ready\")].status}")" = True ] && [ "$(kubectl -n mariadb get sts mariadb-galera -o jsonpath={.status.updatedReplicas})" = 3 ]; do sleep 5; [ $(( $(date +%s)-T2 )) -gt 900 ] && break; done; echo ROLLED $(( $(date +%s)-T2 ))s; sql mariadb-galera-0 mariadb "select @@max_connections"
